class Etiquetas:
    """Etiquetas sin repetir, en orden de llegada, sin distinguir mayúsculas."""

    def __init__(self, *etiquetas):
        self._orden = []
        self._claves = set()
        for e in etiquetas:
            self.agregar(e)

    def agregar(self, etiqueta):
        clave = etiqueta.casefold()
        if clave not in self._claves:
            self._claves.add(clave)
            self._orden.append(etiqueta)

    def __len__(self):
        return len(self._orden)

    def __iter__(self):
        return iter(self._orden)          # un iterador NUEVO en cada llamada

    def __contains__(self, etiqueta):
        return etiqueta.casefold() in self._claves   # O(1) gracias al set

    def __repr__(self):
        return f"Etiquetas{tuple(self._orden)!r}"


