class ConfigTemporal:
    """Cambia claves de un dict durante el bloque y las restaura al salir."""

    def __init__(self, config, **cambios):
        self.config = config
        self.cambios = cambios
        self._antes = {}

    def __enter__(self):
        self._antes = dict(self.config)       # copia para poder restaurar
        self.config.update(self.cambios)
        return self.config

    def __exit__(self, tipo, valor, traza):
        self.config.clear()
        self.config.update(self._antes)
        return False                          # no suprime excepciones


