class Playlist:
    def __init__(self, nombre):
        self.nombre = nombre
        self._canciones = []

    def agregar(self, cancion):
        self._canciones.append(cancion)

    def __len__(self):
        return len(self._canciones)

    def __getitem__(self, indice):
        return self._canciones[indice]

    def __iter__(self):
        return iter(self._canciones)

    def __contains__(self, titulo):
        buscado = titulo.casefold()
        for cancion in self._canciones:
            if cancion.casefold() == buscado:
                return True
        return False

