from enum import Flag, auto


class Permiso(Flag):
    LEER = auto()
    ESCRIBIR = auto()
    EJECUTAR = auto()
    TODOS = LEER | ESCRIBIR | EJECUTAR


LETRAS = [("r", Permiso.LEER), ("w", Permiso.ESCRIBIR), ("x", Permiso.EJECUTAR)]


def a_texto(permisos):
    texto = ""
    for letra, permiso in LETRAS:
        if permiso in permisos:
            texto += letra
        else:
            texto += "-"
    return texto


def desde_texto(texto):
    if len(texto) != 3:
        raise ValueError(f"se esperaban 3 caracteres: {texto!r}")
    resultado = Permiso(0)
    for caracter, (letra, permiso) in zip(texto, LETRAS):
        if caracter == letra:
            resultado |= permiso
        elif caracter != "-":
            raise ValueError(f"carácter no válido {caracter!r} en {texto!r}")
    return resultado

