    def __str__(self):
        nombre = NOMBRES.get(self.valor, str(self.valor))
        return f"{nombre} de {self.palo}"


class Baraja:
    PALOS = ["oros", "copas", "espadas", "bastos"]
    VALORES = [1, 2, 3, 4, 5, 6, 7, 10, 11, 12]

    def __init__(self):
        self._cartas = []
        for palo in self.PALOS:
            for valor in self.VALORES:
                self._cartas.append(Carta(valor, palo))

    def __len__(self):
        return len(self._cartas)

    def __getitem__(self, indice):
        return self._cartas[indice]

    def __setitem__(self, indice, carta):
        self._cartas[indice] = carta

    def __iter__(self):
        return iter(self._cartas)

    def repartir(self, n):
        if n < 0 or n > len(self._cartas):
            raise ValueError(f"no se pueden repartir {n} cartas de {len(self._cartas)}")
        mano = self._cartas[:n]
        del self._cartas[:n]
        return mano

