from dataclasses import dataclass, replace


@dataclass(frozen=True)
class Linea:
    producto: str
    cantidad: int
    precio_unitario: float

    def __post_init__(self):
        if self.cantidad <= 0:
            raise ValueError(f"cantidad no válida: {self.cantidad}")
        if self.precio_unitario < 0:
            raise ValueError(f"precio no válido: {self.precio_unitario}")

    @property
    def subtotal(self):
        return round(self.cantidad * self.precio_unitario, 2)


@dataclass(frozen=True)
class Pedido:
    codigo: str
    lineas: tuple[Linea, ...] = ()
    descuento: float = 0.0

    def __post_init__(self):
        # Aceptamos listas por comodidad, pero guardamos una tupla (inmutable y hashable)
        object.__setattr__(self, "lineas", tuple(self.lineas))
        if not 0 <= self.descuento <= 1:
            raise ValueError(f"descuento fuera de [0, 1]: {self.descuento}")

    @property
    def total(self):
        bruto = sum([linea.subtotal for linea in self.lineas])
        return round(bruto * (1 - self.descuento), 2)

    def con_linea(self, linea):
        return replace(self, lineas=self.lineas + (linea,))

    def sin_producto(self, producto):
        restantes = [linea for linea in self.lineas if linea.producto != producto]
        return replace(self, lineas=tuple(restantes))

