from enum import Enum


class TransicionInvalida(ValueError):
    pass


class EstadoPedido(Enum):
    PENDIENTE = "pendiente"
    PAGADO = "pagado"
    ENVIADO = "enviado"
    ENTREGADO = "entregado"
    CANCELADO = "cancelado"

    def transiciones(self):
        match self:
            case EstadoPedido.PENDIENTE:
                return {EstadoPedido.PAGADO, EstadoPedido.CANCELADO}
            case EstadoPedido.PAGADO:
                return {EstadoPedido.ENVIADO, EstadoPedido.CANCELADO}
            case EstadoPedido.ENVIADO:
                return {EstadoPedido.ENTREGADO}
            case _:
                return set()

    @property
    def es_final(self):
        return not self.transiciones()

    def puede_pasar_a(self, destino):
        return destino in self.transiciones()


class Seguimiento:
    def __init__(self):
        self.estado = EstadoPedido.PENDIENTE
        self.historial = [self.estado]

    def avanzar(self, destino):
        destino = EstadoPedido(destino)   # acepta un miembro o su valor ("pagado")
        if not self.estado.puede_pasar_a(destino):
            raise TransicionInvalida(f"{self.estado.name} -> {destino.name}")
        self.estado = destino
        self.historial.append(destino)
        return destino

