import copy


class Transaccion:
    def __init__(self, datos, ignorar=()):
        self.datos = datos
        self.ignorar = ignorar
        self.estado = "pendiente"
        self._copia = None

    def __enter__(self):
        self._copia = copy.deepcopy(self.datos)
        return self.datos

    def __exit__(self, tipo, valor, traza):
        if tipo is None:
            self.estado = "confirmada"
            return False
        # Restauramos el MISMO diccionario: otros nombres pueden apuntar a él
        self.datos.clear()
        self.datos.update(self._copia)
        self.estado = "revertida"
        return issubclass(tipo, self.ignorar)

