import math
from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable


class Forma(ABC):
    @abstractmethod
    def area(self):
        ...

    @abstractmethod
    def perimetro(self):
        ...

    def describir(self):
        return (f"{type(self).__name__}: área={self.area():.2f}, "
                f"perímetro={self.perimetro():.2f}")


def _validar(*medidas):
    for medida in medidas:
        if medida <= 0:
            raise ValueError(f"las medidas deben ser positivas: {medida}")


class Circulo(Forma):
    def __init__(self, radio):
        _validar(radio)
        self.radio = radio

    def area(self):
        return math.pi * self.radio ** 2

    def perimetro(self):
        return 2 * math.pi * self.radio


class Rectangulo(Forma):
    def __init__(self, ancho, alto):
        _validar(ancho, alto)
        self.ancho = ancho
        self.alto = alto

    def area(self):
        return self.ancho * self.alto

    def perimetro(self):
        return 2 * (self.ancho + self.alto)


class Cuadrado(Rectangulo):
    def __init__(self, lado):
        super().__init__(lado, lado)


@runtime_checkable
class TieneArea(Protocol):
    def area(self) -> float: ...


def area_total(objetos):
    total = 0
    for objeto in objetos:
        if isinstance(objeto, TieneArea):
            total += objeto.area()
    return round(total, 2)

