import math
from functools import total_ordering


@total_ordering
class Fraccion:
    def __init__(self, numerador, denominador=1):
        if not isinstance(numerador, int) or not isinstance(denominador, int):
            raise TypeError("numerador y denominador deben ser enteros")
        if denominador == 0:
            raise ZeroDivisionError("el denominador no puede ser 0")
        if denominador < 0:
            numerador, denominador = -numerador, -denominador
        mcd = math.gcd(numerador, denominador)
        self._num = numerador // mcd
        self._den = denominador // mcd

    @property
    def numerador(self):
        return self._num

    @property
    def denominador(self):
        return self._den

    @staticmethod
    def _convertir(otro):
        """Devuelve otro como Fraccion, o None si no es un tipo compatible."""
        if isinstance(otro, Fraccion):
            return otro
        if isinstance(otro, int):
            return Fraccion(otro)
        return None

    # --- representación ---
    def __repr__(self):
        return f"Fraccion({self._num}, {self._den})"

    def __str__(self):
        if self._den == 1:
            return str(self._num)
        return f"{self._num}/{self._den}"

    # --- aritmética ---
    def __add__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return Fraccion(self._num * otro._den + otro._num * self._den,
                        self._den * otro._den)

    __radd__ = __add__            # la suma es conmutativa

    def __sub__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return Fraccion(self._num * otro._den - otro._num * self._den,
                        self._den * otro._den)

    def __rsub__(self, otro):     # otro - self
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return otro - self

    def __mul__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return Fraccion(self._num * otro._num, self._den * otro._den)

    __rmul__ = __mul__

    def __truediv__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        if otro._num == 0:
            raise ZeroDivisionError("división entre cero")
        return Fraccion(self._num * otro._den, self._den * otro._num)

    def __rtruediv__(self, otro):  # otro / self
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return otro / self

    def __neg__(self):
        return Fraccion(-self._num, self._den)

    def __abs__(self):
        return Fraccion(abs(self._num), self._den)

    def __float__(self):
        return self._num / self._den

    def __bool__(self):
        return self._num != 0

    # --- comparación y hash ---
    def __eq__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return self._num == otro._num and self._den == otro._den

    def __lt__(self, otro):
        otro = self._convertir(otro)
        if otro is None:
            return NotImplemented
        return self._num * otro._den < otro._num * self._den

    def __hash__(self):
        if self._den == 1:
            return hash(self._num)     # igual que el int al que es igual
        return hash((self._num, self._den))

