class Validador:
    """Base sin reglas: las reglas las aportan los mixins."""

    def validar(self, texto):
        return []

    def __call__(self, texto):
        return self.validar(texto)

    def es_valido(self, texto):
        return not self.validar(texto)


class NoVacioMixin:
    def validar(self, texto):
        errores = ["vacío"] if not texto.strip() else []
        return errores + super().validar(texto)


class SinEspaciosMixin:
    def validar(self, texto):
        errores = ["contiene espacios"] if " " in texto else []
        return errores + super().validar(texto)


class MinusculasMixin:
    def validar(self, texto):
        errores = ["no está en minúsculas"] if texto != texto.lower() else []
        return errores + super().validar(texto)


class LongitudMaximaMixin:
    longitud_maxima = 20

    def validar(self, texto):
        errores = []
        if len(texto) > self.longitud_maxima:
            errores.append(f"más de {self.longitud_maxima} caracteres")
        return errores + super().validar(texto)


class ValidadorUsuario(NoVacioMixin, SinEspaciosMixin, MinusculasMixin,
                       LongitudMaximaMixin, Validador):
    longitud_maxima = 12


class ValidadorTitulo(NoVacioMixin, LongitudMaximaMixin, Validador):
    longitud_maxima = 40

