from collections.abc import MutableSequence


class ListaTipada(MutableSequence):
    def __init__(self, tipo, elementos=()):
        self.tipo = tipo
        self._datos = []
        self.extend(elementos)            # extend viene gratis y usa insert()

    def _validar(self, valor):
        if not isinstance(valor, self.tipo):
            raise TypeError(f"se esperaba {self.tipo.__name__}, no {type(valor).__name__}")
        return valor

    # --- los cinco métodos abstractos ---
    def __getitem__(self, indice):
        if isinstance(indice, slice):
            return ListaTipada(self.tipo, self._datos[indice])
        return self._datos[indice]

    def __setitem__(self, indice, valor):
        if isinstance(indice, slice):
            valores = [self._validar(v) for v in valor]   # valida todo ANTES de asignar
            self._datos[indice] = valores
        else:
            self._datos[indice] = self._validar(valor)

    def __delitem__(self, indice):
        del self._datos[indice]

    def __len__(self):
        return len(self._datos)

    def insert(self, indice, valor):
        self._datos.insert(indice, self._validar(valor))

    # --- extras ---
