from dataclasses import dataclass
from enum import StrEnum


class EventoInvalido(ValueError):
    pass


class SaldoInsuficiente(Exception):
    pass


# ---------- Paso 1: tipos ----------
class TipoEvento(StrEnum):
    DEPOSITO = "deposito"
    RETIRO = "retiro"
    TRANSFERENCIA = "transferencia"


def _validar_cuenta(cuenta):
    if not isinstance(cuenta, str) or not cuenta:
        raise EventoInvalido(f"cuenta no válida: {cuenta!r}")


def _validar_importe(importe):
    if isinstance(importe, bool) or not isinstance(importe, int) or importe <= 0:
        raise EventoInvalido(f"importe no válido: {importe!r}")


@dataclass(frozen=True)
class Deposito:
    cuenta: str
    importe: int

    def __post_init__(self):
        _validar_cuenta(self.cuenta)
        _validar_importe(self.importe)


@dataclass(frozen=True)
class Retiro:
    cuenta: str
    importe: int

    def __post_init__(self):
        _validar_cuenta(self.cuenta)
        _validar_importe(self.importe)


@dataclass(frozen=True)
class Transferencia:
    origen: str
    destino: str
    importe: int

    def __post_init__(self):
        _validar_cuenta(self.origen)
        _validar_cuenta(self.destino)
        _validar_importe(self.importe)
        if self.origen == self.destino:
            raise EventoInvalido("origen y destino no pueden coincidir")


# ---------- Paso 2: parsear ----------
def parsear(datos):
    match datos:
        case {"tipo": TipoEvento.DEPOSITO, "cuenta": cuenta, "importe": importe}:
            return Deposito(cuenta, importe)
        case {"tipo": TipoEvento.RETIRO, "cuenta": cuenta, "importe": importe}:
            return Retiro(cuenta, importe)
        case {"tipo": TipoEvento.TRANSFERENCIA, "origen": origen,
              "destino": destino, "importe": importe}:
            return Transferencia(origen, destino, importe)
        case _:
            raise EventoInvalido(f"evento no reconocido: {datos!r}")


# ---------- Paso 5: gestor de contexto ----------
class _Lote:
    """Deshace saldos e historial si el bloque with termina con una excepción."""

    def __init__(self, banco):
        self.banco = banco

    def __enter__(self):
        self._saldos = dict(self.banco._saldos)
        self._historial = list(self.banco.historial)
        return self.banco

    def __exit__(self, tipo, valor, traza):
        if tipo is not None:
            self.banco._saldos = self._saldos
            self.banco.historial = self._historial
        return False                       # nunca suprime la excepción


# ---------- Pasos 3 y 4: el banco ----------
class Banco:
    def __init__(self):
        self._saldos = {}
        self.historial = []

    def _retirar(self, cuenta, importe):
        disponible = self._saldos.get(cuenta, 0)
        if cuenta not in self._saldos or disponible < importe:
            raise SaldoInsuficiente(f"{cuenta}: saldo {disponible}, se piden {importe}")
        self._saldos[cuenta] = disponible - importe

    def _ingresar(self, cuenta, importe):
        self._saldos[cuenta] = self._saldos.get(cuenta, 0) + importe

    def aplicar(self, evento):
        match evento:
            case Deposito(cuenta, importe):
                self._ingresar(cuenta, importe)
            case Retiro(cuenta, importe):
                self._retirar(cuenta, importe)
            case Transferencia(origen, destino, importe):
                self._retirar(origen, importe)     # si falla, aún no se ha tocado nada
                self._ingresar(destino, importe)
            case _:
                raise TypeError(f"no es un evento: {evento!r}")
        self.historial.append(evento)

    def __getitem__(self, cuenta):
        return self._saldos[cuenta]

    def __contains__(self, cuenta):
        return cuenta in self._saldos

    def __len__(self):
        return len(self._saldos)

    def __iter__(self):
        return iter(sorted(self._saldos))

    def total(self):
        return sum(self._saldos.values())

    def resumen(self):
        conteo = {}
        for evento in self.historial:
            match evento:
                case Deposito():
                    tipo = TipoEvento.DEPOSITO
                case Retiro():
                    tipo = TipoEvento.RETIRO
                case Transferencia():
                    tipo = TipoEvento.TRANSFERENCIA
            conteo[tipo] = conteo.get(tipo, 0) + 1
        return conteo

    def lote(self):
        return _Lote(self)

    def procesar(self, lista_de_dicts):
        with self.lote():
            for datos in lista_de_dicts:
                self.aplicar(parsear(datos))
        return len(lista_de_dicts)

