exercises.solution:
class Polinomio:
    def __init__(self, coeficientes):
        coef = list(coeficientes)
        while coef and coef[-1] == 0:      # quita los ceros sobrantes del final
            coef.pop()
        self._coef = tuple(coef)

    @property
    def grado(self):
        return len(self._coef) - 1         # -1 para el polinomio nulo

    # --- representación ---
    def __repr__(self):
        return f"Polinomio({list(self._coef)!r})"

    def __str__(self):
        if not self._coef:
            return "0"
        terminos = []                      # pares (signo, texto sin signo)
        for exp in range(self.grado, -1, -1):
            c = self._coef[exp]
            if c == 0:
                continue
            signo = "-" if c < 0 else "+"
            valor = abs(c)
            if exp == 0:
                cuerpo = str(valor)
            else:
                numero = "" if valor == 1 else str(valor)
                potencia = "x" if exp == 1 else f"x^{exp}"
                cuerpo = numero + potencia
            terminos.append((signo, cuerpo))
        primer_signo, primer_cuerpo = terminos[0]
        texto = ("-" if primer_signo == "-" else "") + primer_cuerpo
        for signo, cuerpo in terminos[1:]:
            texto += f" {signo} {cuerpo}"
        return texto

    # --- protocolo de contenedor ---
    def __len__(self):
        return len(self._coef)

    def __getitem__(self, i):
        return self._coef[i]

    def __iter__(self):
        return iter(self._coef)

    # --- igualdad y hash ---
    def __eq__(self, otro):
        if not isinstance(otro, Polinomio):
            return NotImplemented
        return self._coef == otro._coef

    def __hash__(self):
        return hash(self._coef)

    # --- aritmética ---
    @staticmethod
    def _como_polinomio(x):
        if isinstance(x, Polinomio):
            return x
        if isinstance(x, (int, float)):
            return Polinomio([x])
        return None

    def __add__(self, otro):
        otro = self._como_polinomio(otro)
        if otro is None:
            return NotImplemented
        n = max(len(self), len(otro))
        a = list(self._coef) + [0] * (n - len(self))
        b = list(otro._coef) + [0] * (n - len(otro))
        return Polinomio([x + y for x, y in zip(a, b)])

    __radd__ = __add__

    def __neg__(self):
        return Polinomio([-c for c in self._coef])

    def __sub__(self, otro):
        otro = self._como_polinomio(otro)
        if otro is None:
            return NotImplemented
        return self + (-otro)

    def __rsub__(self, otro):              # otro - self
        otro = self._como_polinomio(otro)
        if otro is None:
            return NotImplemented
        return otro + (-self)

    def __mul__(self, otro):
        otro = self._como_polinomio(otro)
        if otro is None:
            return NotImplemented
        if not self._coef or not otro._coef:
            return Polinomio([])
        resultado = [0] * (len(self) + len(otro) - 1)
        for i, a in enumerate(self._coef):
            for j, b in enumerate(otro._coef):
                resultado[i + j] += a * b
        return Polinomio(resultado)

    __rmul__ = __mul__

    def __pow__(self, n):
        if not isinstance(n, int):
            return NotImplemented
        if n < 0:
            raise ValueError("el exponente debe ser un entero no negativo")
        resultado = Polinomio([1])
        for _ in range(n):
            resultado = resultado * self
        return resultado

    # --- evaluar y derivar ---
    def __call__(self, x):
        resultado = 0
        for c in reversed(self._coef):     # regla de Horner
            resultado = resultado * x + c
        return resultado

    def derivada(self):
        return Polinomio([i * c for i, c in enumerate(self._coef)][1:])

